final class AssetPolicy{const OPTION='zcp_network_asset_policy';public static function defaults():array{return array('mode'=>'allow_site','locked_handles'=>array(),'mandatory_rules'=>array());}public static function all():array{$v=get_site_option(self::OPTION,array());return wp_parse_args(is_array($v)?$v:array(),self::defaults());}public static function update(array $v):bool{if(!current_user_can('manage_network_options'))return false;$mode=in_array($v['mode']??'',array('allow_site','network_only','disabled'),true)?$v['mode']:'allow_site';$handles=$v['locked_handles']??array();if(isset($v['locked_handles_text']))$handles=preg_split('/[\r\n,]+/',(string)$v['locked_handles_text']);$clean=array('mode'=>$mode,'locked_handles'=>array_values(array_filter(array_unique(array_map('sanitize_key',(array)$handles)))),'mandatory_rules'=>array());foreach((array)($v['mandatory_rules']??array()) as $r){$x=\ZinCelestial\Platform\Assets\Rules\RuleValidator::sanitize((array)$r);if($x)$clean['mandatory_rules'][$x['id']]=$x;}return update_site_option(self::OPTION,$clean);}public static function site_rules_allowed():bool{return !is_multisite()||'allow_site'===self::all()['mode'];}public static function locked(string $handle):bool{return is_multisite()&&in_array(sanitize_key($handle),self::all()['locked_handles'],true);}}
